refs = {'blue':(32,58,142), 'purple':(99,63,150), 'green':(44,114,18),
        'orange':(237,137,18), 'red':(208,4,13), 'black':(11,11,11)}
D = {k: np.sqrt(((im-np.array(v,np.int32))**2).sum(2)) for k,v in refs.items()}
dmin = np.minimum.reduce([d for d in D.values()])
MASK = {k: (D[k] < 80) & (D[k] <= dmin) for k in refs}

def line_y(col, color, ylo, yhi):
    """y-centre of the `color` line in column `col` within rows ylo..yhi."""
    ys = [y for y in range(ylo, yhi+1) if MASK[color][y, col]]
    if len(ys) < 2:
        return None
    # cluster consecutive runs, pick the biggest run
    runs = []
    cur = [ys[0]]
    for y in ys[1:]:
        if y == cur[-1]+1: cur.append(y)
        else: runs.append(cur); cur=[y]
    runs.append(cur)
    run = max(runs, key=len)
    return (run[0]+run[-1])/2.0, run[0], run[-1], len(run)

