import numpy as np
from nn import load, assign_nn

def longest_run_ys(mask_col):
    \"\"\"Given bool array down a column, return list of (y_center, length) runs.\"\"\"
    runs=[]; cur=None
    for y,v in enumerate(mask_col):
        if v:
            if cur is None: cur=[y,y]
            else: cur[1]=y
        else:
            if cur is not None:
                if cur[1]-cur[0]+1>=3: runs.append((round((cur[0]+cur[1])/2,1), cur[1]-cur[0]+1))
                cur=None
    if cur is not None and cur[1]-cur[0]+1>=3: runs.append((round((cur[0]+cur[1])/2,1),cur[1]-cur[0]+1))
    return runs

def marker_at(mask, x, half=8, ylo=20, yhi=550):
    \"\"\"Find the (cx,cy) of the longest vertical run in window [x-half,x+half].\"\"\"
    best=(0,None)
    for xx in range(x-half, x+half+1):
        col = mask[ylo:yhi, xx]
        runs = longest_run_ys(col)
        for (cy,ln) in runs:
            cy += ylo
            if ln > best[0]:
                best=(ln,(xx,cy))
    return best  # (length, (cx,cy)) or (0,None)
