import numpy as np
from PIL import Image
from scipy import ndimage

def load(p):
    return np.array(Image.open(p).convert('RGB')).astype(np.int32)

def mask_color(im, ref, tol=90):
    d = np.sqrt(((im - np.array(ref, np.int32))**2).sum(2))
    return d < tol

def black_mask(im, thr=90):
    return im.max(2) < thr

def axis_box(im, min_frac=0.6):
    h, w = im.shape[:2]
    black = black_mask(im)
    colsum = black.sum(0); rowsum = black.sum(1)
    vlines = np.where(colsum > h*min_frac)[0]
    hlines = np.where(rowsum > w*min_frac)[0]
    if len(vlines)==0 or len(hlines)==0:
        return None
    return (int(vlines.min()), int(vlines.max()), int(hlines.min()), int(hlines.max()))

def markers_in_box(mask, box, min_area=12, max_area=4000):
    """Connected components inside box; return (cx,cy,area) list."""
    x0,x1,y0,y1 = box
    sub = mask.copy()
    # zero outside box
    sub[:max(0,y0-1),:] = False
    sub[min(h, y1+1):,:] = False
    sub[:,:max(0,x0-1)] = False
    sub[:,min(w, x1+1):] = False
    h, w = mask.shape
    sub = np.zeros_like(mask)
    sub[y0:y1+1, x0:x1+1] = mask[y0:y1+1, x0:x1+1]
    lab, n = ndimage.label(sub)
    out = []
    for i in range(1, n+1):
        comp = lab==i
        area = comp.sum()
        if area < min_area or area > max_area:
            continue
        ys, xs = np.where(comp)
        out.append((xs.mean(), ys.mean(), area))
    return out

