            sp=min(waist,key=lambda t:abs(t-(a0+b0)//2))
            if (sp-a0)>=3 and (b0-sp)>=3:
                splits.append((a0,sp-1)); splits.append((sp+1,b0))
            else:
                splits.append((a0,b0))
        else:
            splits.append((a0,b0))
    res=[]
    for (a0,b0) in splits:
        subm=sub[a0:b0+1,:]
        yy,xx=np.where(subm)
        if len(yy)<8: continue
        res.append(dict(cy=float(a0+yy.mean()), cx=float(xx.mean()), a0=int(a0),b0=int(b0), area=int(len(yy)),
                        h=int(b0-a0+1), wspan=int(xx.max()-xx.min()+1)))
    return res

