def dist(im, ref):
    return np.sqrt(((im-np.array(ref,np.int32))**2).sum(2))

def color_mask(im, ref, tol=70):
    return dist(im,ref) < tol

def erode(m, r):
    if r<=0: return m
    s=np.ones((2*r+1,2*r+1),bool)
    return ndi.binary_erosion(m, structure=s)

def markers(mask, min_area=25, max_area=2000):
    lab,n = ndi.label(mask)
    out=[]
    for i in range(1,n+1):
        c=lab==i
        a=int(c.sum())
        if a<min_area or a>max_area: continue
        ys,xs=np.where(c)
        out.append(dict(cx=float(xs.mean()), cy=float(ys.mean()), a=a,
                        x0=int(xs.min()),x1=int(xs.max()),y0=int(ys.min()),y1=int(ys.max())))
    return out

def calib(task):
    def mk(ticks,log):
        p1=ticks[0]['pixel_x' if 'pixel_x' in ticks[0] else 'pixel_y']; v1=ticks[0]['value']
        p2=ticks[1]['pixel_x' if 'pixel_x' in ticks[1] else 'pixel_y']; v2=ticks[1]['value']
        if log:
            l1,l2=np.log10(v1),np.log10(v2)
            f=lambda px: 10**(l1+(px-p1)/(p2-p1)*(l2-l1))
        else:
            f=lambda px: v1+(px-p1)/(p2-p1)*(v2-v1)
        return f
    return mk(task['x_ticks'],task['x_scale']=='log'), mk(task['y_ticks'],task['y_scale']=='log')

def tasks():
    return {t['id']:t for t in json.load(open('tasks.json'))}
