    lab = np.zeros((H,W), int)
    comp = []
    nxt = 1
    for i in range(H):
        row = m[i]
        for j in range(W):
            if row[j] and lab[i,j]==0:
                stack=[(i,j)]; lab[i,j]=nxt; pts=[]
                while stack:
                    y,x = stack.pop(); pts.append((y,x))
                    for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                        ny,nx=y+dy,x+dx
                        if 0<=ny<H and 0<=nx<W and m[ny,nx] and lab[ny,nx]==0:
                            lab[ny,nx]=nxt; stack.append((ny,nx))
                comp.append(pts)
                nxt+=1
    return lab, comp

def stats(m, pts):
    ys = [p[0] for p in pts]; xs=[p[1] for p in pts]
